## Test File 2: E2E Test

Create `test-acp-activity-tracking-e2e.ts` in repo root:

```typescript
import { acp_delegate } from './src/tool/acp-delegate'

// Simple 3-task activity template for testing
const testTemplate = {
  name: 'test-acp-tracking',
  tasks: [
    { id: 'task-1', prompt: { template: 'Create file test1.txt with content "Task 1"' } },
    { id: 'task-2', prompt: { template: 'Create file test2.txt with content "Task 2"' } },
    { id: 'task-3', prompt: { template: 'Create file test3.txt with content "Task 3"' } }
  ]
}

async function runE2ETest() {
  console.log('Starting ACP activity tracking E2E test...')

  // Check Docker availability
  const dockerAvailable = await checkDocker()
  if (!dockerAvailable || {{skipE2ETest}}) {
    console.log('Skipping E2E test (Docker unavailable or skipE2ETest=true)')
    return
  }

  // Ensure test container running
  await ensureContainer('{{testDockerContainer}}')

  // Track events received
  const events: any[] = []
  const eventHandler = (event: any) => events.push(event)

  // Delegate activity
  const result = await acp_delegate({
    target: 'docker://{{testDockerContainer}}',
    taskDescription: 'Test ACP activity tracking',
    prompt: 'Execute test activity',
    shareImpulses: [],
    timeout: 300
  })

  // Validate event sequence
  const startEvents = events.filter(e => e.type === 'activity-start')
  const progressEvents = events.filter(e => e.type === 'activity-progress')
  const completeEvents = events.filter(e => e.type === 'activity-complete')

  console.assert(startEvents.length === 1, 'Expected exactly 1 start event')
  console.assert(progressEvents.length === 3, 'Expected 3 progress events')
  console.assert(completeEvents.length === 1, 'Expected exactly 1 complete event')

  // Validate metrics
  const completion = completeEvents[0]
  console.assert(completion.duration > 0, 'Duration should be > 0')
  console.assert(completion.tokensUsed.input > 0, 'Input tokens should be > 0')
  console.assert(completion.tasksCompleted === 3, 'Should complete 3 tasks')

  console.log('✓ All events received')
  console.log('✓ Metrics accurate')
  console.log('E2E test passed!')
}

runE2ETest().catch(console.error)
```

